from collections import defaultdict

def count_groups(n, nums):
    dp = defaultdict(int)
    mod = 1000000007

    for i, num in enumerate(nums):
        for j in range(30):
            if num & (1 << j):
                dp[j] += 1
                for k in range(j):
                    if num & (1 << k):
                        dp[j] = min(dp[j], dp[k])

    def factorial_mod(n):
        fact = 1
        for i in range(1, n + 1):
            fact = (fact * i) % mod

        return fact

    total = 0
    for k in range(n + 1):
        k_bin = k.bit_length()
        current = factorize(k_bin)

        for j in range(max(0, k_bin - 30), k_bin + 1):
            current[j] += k

        total += current[k - 1]
        total %= mod

    return total * factorial_mod(k + 1) % mod

def factorize(num):
    dp = defaultdict(int)
    dp[0] = 1

    for i in range(1, num + 1):
        dp[i] += pow(2, i) + pow(3, i) + pow(6, i) + pow(12, i) + pow(20, i) + pow(30, i) + pow(42, i) + pow(56, i)

    return dp

