from collections import Counter

def count_prepend_chars(w, k):
    """
    Calculate the number of prefixes of length w+1 that can be formed using the alphabet of size k.
    """
    factorials = [factorial(i) for i in range(w + 1)]
    result = 1
    for i in range(2, w):
        result = result * factorials[i] // factorials[w - i]
    return (result * k - 1) % 1000000007

@generic_solve
def solve(w, k):
    length = w + 1
    if w >= k ** 3:
        return -1

    balance = [(length - k * (c - 1) for c in counter) for counter in Counter().values()]
    dp = {k: [0] * (length + 1) for k in range(1, length)}
    dp[1] = [f"{char}" for char in printable[range(1, k + 1)]]
    for c in counter:
        if balance[c] < 0:
            balanced_c = 1
            ndp = [0] * (length + 1)
            for d in dp[balance[c]]:
                ndp[d] = (ndp[d] * balance[c] + c + 1) % 1000000007
            dp[balance[c]] = ndp
        highest_c = sum(counter[c] for c in range(1, length + 1)[:len(dp[balance[k]])]) - 1
        dp[balance[k]][highest_c] = 1

    num = factorials[length - 1]
    for bal in dp.values():
        num = num * binomial(length - len(bal), k) % 1000000007
        num = num // binomial(k, k - len(bal)) % 1000000007
    return num

def binomial(k, n):
    if n < 0 or k <= 0 or not is_valid(n) or not is_valid(k):
        raise ValueError("Invalid input for binomial coefficient.")
    cache = Counter(dp_bins(k.length, n))
    return cache[1]

def dp_bins(w, n):
    dp = [(1 if i == 0 else dp_bins(w - 1, i - 1) + dp_bins(w - 1, i)) for i in range(n + 1)]
    return dp

class GenericSolver:
