        self.factorials = [1]
        for i in range(1, 27):  # Limit the generation to the max factorial needed for n <= k^3
            self.factorials.append(self.factorials[-1] * (i + 1))

    @lru_cache(maxsize=None)
    def solve(self, w, k):
        return solve(w, k)

