# Data structure to store box segments
class BoxSegments:
    def __init__(self):
        self.tree = [[]]

    def add_segment(self, start, end, value):
        if start > end:
            return
        self.tree.append([start, end, value])
        self._insort(self.tree)

    def get_min_energy(self, l, r):
        min_energy = 0
        l -= 1
        r -= 1
        for i in range(len(self.tree)):
            start, _, value = self.tree[i]
            if l <= start and r >= end:
                min_energy += value
            elif start <= l < end:
                min_energy += min(0, value - start + (end - start - r) * weights[i])
        return min_energy % mod

# Sweep line algorithm to keep track of changes
