    def __init__(self):
        self.box_segments = BoxSegments()
        self.sweep_points = set()
        self.sweep_points_visited = set()

    def push_event(self):
        while self.sweep_points:
            point, value = self.sweep_points.pop()
            self.sweep_points_visited.add(point)
            if point + 1 in self.sweep_points and value == 0:
                self.sweep_points.remove(point + 1)
            self.box_segments.add_segment(point, point + 1, value)

    def reset(self):
        while self.sweep_points:
            point, value = self._pop()
            self.box_segments.add_segment(point + 1, point + 1, 0)
        self.sweep_points = set()

    def poll_events(self):
        while self.sweep_points:
            point, value = self._pop()
            if point + 1 in self.sweep_points:
                self._prevent_pre_order_repeats(point + 1)

    def _pre_val_changes(self):
        pass

    def _insort(self, tree):
        idx = len(tree) - 1
        value = tree[-1]
        while idx:
            if tree[idx] == value:
                break
            elif tree[idx] > value:
                tree[idx - 1] = tree[idx]
                tree[idx] = value
            else:
                break
            idx -= 1
        tree[idx] = value

    def _prevents_pre_order_repeats(self, point):
        if point + 1 not in self.sweep_points:
            self.sweep_points.add(point + 1)

    def _pop(self):
        idx = sorted(list(self.sweep_points_visited))[-1] + 1
        tree = self.tree
        parent_ptr, value_ptr = 0, idx
