To solve this problem, we can use the Knuth-Morris-Pratt (KMP) algorithm for pattern matching and the Boyer-Moore string search algorithm for determining the best verse by maximizing the beauty of the stanzas. The solution involves sorting the words by their order in lexicographical order and then iterating through all possible stanzas, calculating their beauty, and keeping track of the maximum beauty.

```python
from collections import Counter

def kmp_search(text, pattern):
    m = len(pattern)
    next = [0] * m
    j = 0
    for i in range(1, m):
        while j and pattern[j] != pattern[i]:
            j = next[j - 1]
        if pattern[j] == pattern[i]:
            next[i] = j + 1
            j += 1
    return j >= 0

def boyer_moore(text, pattern):
    m = len(pattern)
    next = [0] * m
    for i in range(1, m):
        next[i] = m
        for j in range(i, m):
            if pattern[j] == pattern[next[i] - 1]:
                next[i] = j + 1
                break
    for i in range(m - 1):
        j = next[i]
        while j and text[j] != pattern[m - i - 1]:
            j = next[j - 1]
        if j:
            next[i + 1] = j + 1
    next[m] = m
    return next

def find_best_verse(words):
    words_count = Counter(words)
    best_beauty = 0
    for i in range(1 << len(words)):
        stanzas = [list() for _ in range(len(words))]
        for j in range(len(words)):
            if (i >> j) & 1:
                stanzas[j] = words[j].copy()
        stanzas.sort(key=lambda pair: (len(pair[0]), len(pair[1])))
        beauty = 0
        for i in range(len(stanzas)):
            stanzas[i].sort()
            longest_common_prefix, longest_common_suffix = min(stanzas[i]), max(stanzas[i])
            # Convert tuples to strings for comparison
            stanzas[i] = tuple(''.join(stanzas[i]))
            stanzas[i] = list(stanzas[i])
            longest_common_prefix = ''.join(longest_common_prefix)
            longest_common_suffix = ''.join(longest_common_suffix)
            if longest_common_prefix:
                beauty += int(min(len(longest_common_prefix), len(longest_common_suffix)) ** 2)
        best_beauty = max(best_beauty, beauty)
    return best_beauty

def solve():
    T = int(input())
    for _ in range(T):
        N = int(input())
        words = [input() for _ in range(N)]
        print(find_best_verse(words))

