        dp[risks[0][i-1]] = 1  # Type i is included in the first organism
        for j in range(1, N):
            new_dp = [0] * K
            for type_ in range(K):
                effective_risk = float('inf')
                if type_ > 0:
                    effective_risk, _, _ = dp[calculate_effective_risk(dp[effective_risk], type_)]
                    for n in reversed(range(T)):
                        if dp[n] or n >= T:
                            effective_risk = min(effective_risk, max(dp[n-2], n))
                    new_dp[type_] += effective_risk
                else:
                    for n in range(dp[0], T + 1, dp[0]):
                        if dp[n] or n < T:
                            new_dp[type_] += dp[n] + j * t[type_] + n
            dp = new_dp
