from collections import defaultdict, deque

def bfs_k_grasshopper_range(array, range_start, range_end, k):
    n = len(array)
    cell_pairs = []
    for i in range(n):
        if i >= range_start:
            left = array[:min(range_start, array.index(i))]
            if i not in left:
                cell_pairs.append((left, i))
        if i >= range_end:
            right = array[min(array.index(i), range_end):range_end + len(array)]
            if i not in right:
                cell_pairs.append((right, i))

    visited = set()
    queue = deque(cell_pairs)
    while queue:
        cell, value = queue.popleft()
        if value <= k:
            for new_value in range(k, min(value + k, len(cell) + 1)):
                if new_value in visited:
                    continue
                if array[0] <= value + new_value - 1 and new_value not in array[value + new_value:k - value + 1]:
                    visited.add(new_value)
                    if new_value < value:
                        queue.append((array[:new_value], new_value))
                    if new_value < len(array):
                        queue.append((array[value:new_value], new_value))

    k_value = set()
    for i, l in enumerate(array):
        new_value = len(array) - i - array.index(i) - 1
        if new_value <= k:
            if new_value not in visited:
                k_value.add(new_value)

    return min(k_value) if k_value else len(array)

