from heapq import *

def min_presidios(n, colors):
    mod = defaultdict(list)
    for i, color in enumerate(colors):
        mod[color].append(i)

    k_to_presidios = {}
    for k in range(1, n + 1):
        prefix_sums = [0] * (n + 1)
        for color, colors_color in mod.items():
            prefix_sums[k + 1] += k
            prefix_sums[k + 1] -= len(colors_color)

        # Use a min-heap to keep the top k elements of the prefix sums array
        heap = []
        for i, count in enumerate(prefix_sums):
            if i in k_to_presidios:
                count += k_to_presidios[i]
            if count <= k:
                heappush(heap, count)
            elif count > k:
                break
            if len(heap) > k:
                heappop(heap)

        k_to_presidios[k] = len(heap)

    return list(k_to_presidios[k]) + [n-x for x in sorted(k_to_presidios[k] + [n] - range(n, 0, -1))]

