def calculate_liar_options(n, k):
    # Base cases
    if k == 0:
        return 1 if n % 2 == 0 else 0
    if n == 1:
        return 0 if k != 0 else 1
    # Recursive cases
    if k == 1:
        return 1
    for i in range(k, n):
        if i % 2 == n % 2:
            options = (calculate_liar_options(i, k - 1) + calculate_liar_options(n - i, k)) % 777777777
    if n % 2 == 0:
        options += calculate_liar_options(n // 2, k)
    else:
        options += calculate_liar_options(n // 2 + 1, k)
    return options % 777777777


