def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def is_coprime(a, b):
    return gcd(a, b) == 1

def super_function(N, K, M):
    MOD = 1000000007
    target_SuperFuntion = 0
    max_value = 0
    initial_list = []

    for i in range(1, N+1):
        if len(initial_list) < K:
            if is_coprime(i, N) == True and initial_list == []:
                initial_list.append(i)
                max_value = i

    for number in initial_list:
        single_SuperFuntion = 0
        for exponent in range(1, K+1):
            single_SuperFuntion += number ** exponent % M

        max_value = max(max_value, single_SuperFuntion)
        target_SuperFuntion = (target_SuperFuntion + max_value) % M

    return target_SuperFuntion

