from functools import lru_cache
from collections import defaultdict

def find_common_prefix(strings):
    if not strings: return ""
    shortest = min(strings, key=len)
    for i, ch in enumerate(shortest):
        for other in strings:
            if other[i] != ch:
                return shortest[:i]
    return shortest

def find_common_suffix(strings):
    if not strings: return ""
    longest = max(strings, key=len)
    for i, ch in enumerate(longest[::-1]):
        for other in strings:
            if other[::-1][i] != ch:
                return longest[i+1:]
    return longest

def compute_beauty(stanza):
    prefixal_rhyme = find_common_prefix(stanza)
    suffixal_rhyme = find_common_suffix(stanza)
    num_chars = len(prefixal_rhyme)
    return (min(len(prefixal_rhyme), len(suffixal_rhyme)) ** 2)

def compute_max_beauty(word_list):
    word_counts = defaultdict(int)
    word_list.sort(key=lambda x: len(x), reverse=True)

    @lru_cache(maxsize=None)
    def calculate_beauty(stanza, index):
        if index == len(stanza):
            return 0
        current_word = stanza[index]
        beauty = 0
        for i, word in enumerate(stanza):
            # Skip if the word is used up
            if i >= word_counts[word]: continue
            beauty = max(beauty, calculate_beauty(stanza[:index] + [stanza[index+1:]], index+1))
        word_counts[current_word] += 1
        return beauty

    return calculate_beauty(word_list, 0)

T = int(input())
for _ in range(T):
    N = int(input())
    word_list = []
    for _ in range(N):
        word_list.append(input())
