def solve_for_partition(vertices):
    color = [None] * vertices
    queue = [vertices]

    while queue:
        current = queue.pop(0)
        for i in range(vertices):
            if color[i] is None and undirected_graph[current][i] and color[current] == color[i]:
                return "N " + str(i)
            elif color[i] is None and undirected_graph[current][i]:
                color[i] = 1 - color[current]
                queue.append(i)

    return "Y " + str(sum(color == None, key=color.count))

