def solve(n, k, t, genome, gene_types, add_rates, difs, difsTerm):
    possibleGenes = [0] * k

    for i in range(1, n+1):
        if i in difsTerm:
            for j in difsTerm[i]:
                possibility = 0
                for l, rate in enumerate(difs[i][genome[i-1]].items()):
                    possibility += rate[1] * (possibility + add_rates[possibility + rate[0]])
                possibleGenes[gene_types[l]] = min(possibleGenes[gene_types[l]], possibility)
        else:
            for l, rate in enumerate(difs[i][genome[i-1]].items()):
                possibleGenes[gene_types[l]] = min(possibleGenes[gene_types[l]], rate[1] + add_rates[rate[0]])

    res = set()
    for i in range(1, n+1):
        res.add(possibleGenes[i-1])

