def is_coprime(x, n):
    return gcd(x, n) == 1

def gcd(x, y):
    while y:
        x, y = y, x % y
    return x

def super_function(n, k, m):
    result = 0
    for i in range(1, n+1):
        if is_coprime(i, n) and i <= n:
            result = (result + pow(i, k, m)) % m
    return result

