from math import pow

def count_possible_sequences(num_people, lies):
    dp = [[0] * (num_people + 1) for _ in range(num_people)]
    dp[0][0] = 1
    for i in range(1, num_people):
        if i <= lies:
            for j in range(1, i + 2):
                for _ in range(j + 2 - 1, i):
                    dp[i][j] = dp[i][j] + dp[i - 1][_]
        else:
            for j in range(i + 1, 2 * num_people):
                for _ in range(j + 1, i + 1):
                    dp[i][j] = dp[i][j] + dp[i - 1][_]
    return dp[num_people - 1][lies]

