from functools import lru_cache

def count_answers(n, k):
    @lru_cache(None)
    def dfs(n, k):
        if n == 1:
            return k == 0
        if (k == 0 or k == n) and k != n and k != 1:
            return True
        if k != 0:
            return False
        if (n - 1) * (k // 2) >= n:
            return False
        return any(dfs(n, k-i) for i in range(1, int(n // 2) + 1))

    return sum(dfs(n, i) for i in range(k+1, n))

